bundle={'schema_version':'benchmark-research-r1.1','checked_at':DATE,'status':'research_candidate_requires_parent_QA','baseline':{'path':str(base),'sha256':hashlib.sha256(base.read_bytes()).hexdigest(),'registry_count':len(old),'preserved_node_ids':[x['node_id'] for x in old]},'policy':{'metadata_only':True,'questions_or_answers_collected':False,'restricted_files_downloaded':False,'code_or_models_executed':False,'device_or_account_accessed':False,'scores_imported':False},'availability_vocabulary':{'public':'公开题/任务或生成器入口；不代表所有标签或运行资源公开，见access note','gated':'至少完整访问或运行资源需账户/同意条款/审批','private_described':'仅公开描述，完整集不公开','results_only':'只有公开结果，无可核实数据入口'},'records':records,'coverage_gaps':['未宣称覆盖所有公开或非公开评测；非公开项目只能登记运营方公开说明。','HumanEval/LiveCodeBench/SWE-bench等已有registry节点本轮不覆盖或重复新增。','无成绩快照；部分metric细则、许可和commit保留unknown/待核验。','ScreenSpot拟定仓库URL抓取cache miss，未据此录入；未重试GPQA。']}
P.joinpath('records.json').write_text(json.dumps(bundle,ensure_ascii=False,indent=2)+'\n')
md=['# ModelAtlas 评测目录扩充候选（metadata only）','',f'核验日期：{DATE}。新增 {len(records)} 条版本/分片记录；原11项不变。不是完整全球目录，也不是排行榜。','', '## 先看重要边界','- MMMU test答案已公开；MathVista test标签仍声明不公开。公开入口与完整可复现不是同一概念。','- GAIA须门控并禁止可爬重发；WorkArena代码公开而运行实例需审批。','- OSWorld原版/Verified、WebLINX 1.0/1.1、LongBench v1/v2独立记录；RULER历史pipeline已deprecated仍保留。','- OCRBench v2明确研究用途、非商业，不能把根仓库MIT当全部数据授权。','- 全部成绩为空，只链接官方结果；没有下载题库、答案、受限包，未执行代码或使用账号/设备。','','## 目录']
